//! Full-rank triclinic periodic lattices for D=2 and D=3.
//!
//! Unlike PeriodicBox, a lattice cell is generated by arbitrary independent
//! basis vectors. Fractional-coordinate rounding is used only to choose a
//! canonical fundamental cell. It is NOT used as a nearest-image solver:
//! nearest images are found by bounded QR sphere decoding.
//!
//! The current reference implementation intentionally supports only full-rank
//! 2D/3D lattices. Mixed periodic rank and non-orthogonal embedded subspaces
//! require a separate contract and are not silently approximated here.

use std::error::Error;
use std::fmt;

use nalgebra::{SMatrix, SVector};

use crate::periodic::LatticeOffset;

const MAX_EXACT_LATTICE_INDEX: f64 = 4_503_599_627_370_495.0; // 2^52 - 1
const MIN_RELATIVE_QR_PIVOT: f64 = 1.0e-8;
const QR_ROUNDING_PAD: f64 = 64.0 * f64::EPSILON;

/// Failure to construct or query a triclinic periodic lattice.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum PeriodicLatticeError {
    InvalidDimension,
    UnsupportedDimension { dimension: usize },
    NonFiniteOrigin { axis: usize },
    NonFiniteBasis { row: usize, column: usize },
    DegenerateBasis { column: usize },
    CoordinatePrecisionLimit { axis: usize },
    InvalidSearchBudget,
    SearchBudgetExceeded { max_nodes: usize },
    NumericRange { field: &'static str },
}

impl fmt::Display for PeriodicLatticeError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::InvalidDimension => write!(f, "periodic lattice requires D >= 1"),
            Self::UnsupportedDimension { dimension } => {
                write!(f, "triclinic reference lattice supports D=2 or D=3, got D={dimension}")
            }
            Self::NonFiniteOrigin { axis } => {
                write!(f, "non-finite periodic lattice origin on axis {axis}")
            }
            Self::NonFiniteBasis { row, column } => {
                write!(f, "non-finite lattice basis entry at row {row}, column {column}")
            }
            Self::DegenerateBasis { column } => {
                write!(f, "periodic lattice basis is singular or ill-conditioned at column {column}")
            }
            Self::CoordinatePrecisionLimit { axis } => {
                write!(f, "periodic lattice coordinate exceeds the exact image-index envelope on axis {axis}")
            }
            Self::InvalidSearchBudget => write!(f, "closest-image search budget must be positive"),
            Self::SearchBudgetExceeded { max_nodes } => {
                write!(f, "closest-image search exhausted its node budget ({max_nodes})")
            }
            Self::NumericRange { field } => {
                write!(f, "periodic lattice numeric-range failure in {field}")
            }
        }
    }
}

impl Error for PeriodicLatticeError {}

/// Canonical point plus the integer image from which it was reduced.
#[derive(Clone, Debug, PartialEq)]
pub struct WrappedLatticePoint<const D: usize> {
    pub position: SVector<f64, D>,
    pub image_offset: LatticeOffset<D>,
}

/// Result of an exact-within-budget closest-image query.
#[derive(Clone, Debug, PartialEq)]
pub struct ClosestLatticeImage<const D: usize> {
    /// Integer n minimizing ||displacement + B*n|| within the bounded search.
    pub image_offset: LatticeOffset<D>,
    /// Minimum-image displacement in the original Cartesian coordinates.
    pub displacement: SVector<f64, D>,
    pub distance_squared: f64,
    /// Number of integer candidates visited by the sphere decoder.
    pub search_nodes: usize,
}

/// A full-rank D-dimensional periodic lattice with columns of basis as
/// independent translation vectors.
#[derive(Clone, Debug)]
pub struct PeriodicLattice<const D: usize> {
    origin: SVector<f64, D>,
    basis: SMatrix<f64, D, D>,
    q: SMatrix<f64, D, D>,
    r: SMatrix<f64, D, D>,
    squared_basis_scale: f64,
    /// Conservative diagonal-pivot ratio from the reorthogonalized QR factor.
    /// This is a rejection/diagnostic proxy, not a spectral condition number.
    min_relative_qr_pivot: f64,
}

impl<const D: usize> PeriodicLattice<D> {
    /// Construct a full-rank 2D or 3D lattice.
    ///
    /// QR is computed using twice-reorthogonalized modified Gram-Schmidt. A
    /// small relative diagonal pivot is rejected rather than allowing an
    /// unstable image search to silently return a potentially wrong answer.
    pub fn new(
        origin: SVector<f64, D>,
        basis: SMatrix<f64, D, D>,
    ) -> Result<Self, PeriodicLatticeError> {
        if D == 0 {
            return Err(PeriodicLatticeError::InvalidDimension);
        }
        if D != 2 && D != 3 {
            return Err(PeriodicLatticeError::UnsupportedDimension { dimension: D });
        }
        for axis in 0..D {
            if !origin[axis].is_finite() {
                return Err(PeriodicLatticeError::NonFiniteOrigin { axis });
            }
        }
        for row in 0..D {
            for column in 0..D {
                if !basis[(row, column)].is_finite() {
                    return Err(PeriodicLatticeError::NonFiniteBasis { row, column });
                }
            }
        }

        let basis_scale = basis.norm();
        if !basis_scale.is_finite() || basis_scale <= 0.0 {
            return Err(PeriodicLatticeError::DegenerateBasis { column: 0 });
        }
        let squared_basis_scale = basis_scale * basis_scale;
        if !squared_basis_scale.is_finite() || squared_basis_scale <= 0.0 {
            return Err(PeriodicLatticeError::NumericRange {
                field: "squared lattice basis scale",
            });
        }

        let mut q = SMatrix::<f64, D, D>::zeros();
        let mut r = SMatrix::<f64, D, D>::zeros();
        let mut minimum_pivot_ratio = f64::INFINITY;

        for column in 0..D {
            let mut vector = basis.column(column).into_owned();

            // Reorthogonalize to reduce loss of orthogonality for skewed cells.
            for _pass in 0..2 {
                for previous in 0..column {
                    let q_column = q.column(previous).into_owned();
                    let coefficient = q_column.dot(&vector);
                    r[(previous, column)] += coefficient;
                    vector -= q_column * coefficient;
                }
            }

            let diagonal = vector.norm();
            let relative_pivot = diagonal / basis_scale;
            if !diagonal.is_finite()
                || diagonal <= 0.0
                || !relative_pivot.is_finite()
                || relative_pivot < MIN_RELATIVE_QR_PIVOT
            {
                return Err(PeriodicLatticeError::DegenerateBasis { column });
            }
            r[(column, column)] = diagonal;
            q.set_column(column, &(vector / diagonal));
            minimum_pivot_ratio = minimum_pivot_ratio.min(relative_pivot);
        }

        let gram_error = (q.transpose() * q - SMatrix::<f64, D, D>::identity()).norm();
        if !gram_error.is_finite() || gram_error > 1.0e-9 * D as f64 {
            return Err(PeriodicLatticeError::NumericRange {
                field: "QR orthogonality residual",
            });
        }
        let reconstruction_error = (basis - q * r).norm() / basis_scale;
        if !reconstruction_error.is_finite() || reconstruction_error > 1.0e-9 {
            return Err(PeriodicLatticeError::NumericRange {
                field: "QR reconstruction residual",
            });
        }

        Ok(Self {
            origin,
            basis,
            q,
            r,
            squared_basis_scale,
            min_relative_qr_pivot: minimum_pivot_ratio,
        })
    }

    pub fn origin(&self) -> &SVector<f64, D> {
        &self.origin
    }

    /// Basis columns are the periodic translation vectors.
    pub fn basis(&self) -> &SMatrix<f64, D, D> {
        &self.basis
    }

    pub fn min_relative_qr_pivot(&self) -> f64 {
        self.min_relative_qr_pivot
    }

    /// Cartesian translation represented by an explicit integer image offset.
    pub fn offset_vector(
        &self,
        offset: LatticeOffset<D>,
    ) -> Result<SVector<f64, D>, PeriodicLatticeError> {
        let mut integer = SVector::<f64, D>::zeros();
        for axis in 0..D {
            let value = offset.periods[axis] as f64;
            if value.abs() > MAX_EXACT_LATTICE_INDEX {
                return Err(PeriodicLatticeError::CoordinatePrecisionLimit { axis });
            }
            integer[axis] = value;
        }
        let translation = self.basis * integer;
        if !translation.iter().all(|value| value.is_finite()) {
            return Err(PeriodicLatticeError::NumericRange {
                field: "lattice image translation",
            });
        }
        Ok(translation)
    }

    pub fn apply_offset(
        &self,
        point: &SVector<f64, D>,
        offset: LatticeOffset<D>,
    ) -> Result<SVector<f64, D>, PeriodicLatticeError> {
        if !point.iter().all(|value| value.is_finite()) {
            return Err(PeriodicLatticeError::NumericRange {
                field: "point before image translation",
            });
        }
        let translated = point + self.offset_vector(offset)?;
        if !translated.iter().all(|value| value.is_finite()) {
            return Err(PeriodicLatticeError::NumericRange {
                field: "translated point",
            });
        }
        Ok(translated)
    }

    /// Reduce a Cartesian point into the half-open fundamental parallelepiped
    /// origin + B*[0,1)^D. The returned offset reconstructs the input.
    pub fn wrap_point(
        &self,
        point: &SVector<f64, D>,
    ) -> Result<WrappedLatticePoint<D>, PeriodicLatticeError> {
        if !point.iter().all(|value| value.is_finite()) {
            return Err(PeriodicLatticeError::NumericRange {
                field: "input point",
            });
        }
        let delta = point - self.origin;
        if !delta.iter().all(|value| value.is_finite()) {
            return Err(PeriodicLatticeError::NumericRange {
                field: "point-origin displacement",
            });
        }

        let fractional = self.solve_basis_coordinates(&delta)?;
        let mut canonical_fractional = SVector::<f64, D>::zeros();
        let mut offsets = [0_i64; D];

        for axis in 0..D {
            let coordinate = fractional[axis];
            if !coordinate.is_finite() || coordinate.abs() > MAX_EXACT_LATTICE_INDEX {
                return Err(PeriodicLatticeError::CoordinatePrecisionLimit { axis });
            }
            let image = coordinate.floor();
            if image < i64::MIN as f64 || image > i64::MAX as f64 {
                return Err(PeriodicLatticeError::CoordinatePrecisionLimit { axis });
            }
            offsets[axis] = image as i64;
            let canonical = coordinate - image;
            if !canonical.is_finite() || !(0.0..1.0).contains(&canonical) {
                return Err(PeriodicLatticeError::NumericRange {
                    field: "canonical fractional coordinate",
                });
            }
            canonical_fractional[axis] = canonical;
        }

        let canonical_position = self.origin + self.basis * canonical_fractional;
        if !canonical_position.iter().all(|value| value.is_finite()) {
            return Err(PeriodicLatticeError::NumericRange {
                field: "canonical Cartesian position",
            });
        }

        Ok(WrappedLatticePoint {
            position: canonical_position,
            image_offset: LatticeOffset::new(offsets),
        })
    }

    /// Find the nearest periodic representative by solving
    /// argmin_n ||displacement + B*n||.
    ///
    /// A Babai nearest-plane point supplies an initial radius, after which a
    /// bounded QR sphere decoder enumerates every integer point inside that
    /// radius. Search-budget exhaustion is an error; the current best point is
    /// never returned as though it were proven globally nearest.
    /// Find the nearest periodic representative under the canonical tie rule.
    ///
    /// The input is oriented so its first nonzero Cartesian component is
    /// positive before the search. This makes the exact-distance tie rule
    /// reversal-odd: minimum_image(-d) = -minimum_image(d), including at
    /// Voronoi facets. Returned offsets are always expressed in the original
    /// caller's lattice orientation.
    pub fn minimum_image_displacement(
        &self,
        displacement: &SVector<f64, D>,
        max_search_nodes: usize,
    ) -> Result<ClosestLatticeImage<D>, PeriodicLatticeError> {
        let reverse = displacement
            .iter()
            .find(|component| **component != 0.0)
            .is_some_and(|component| *component < 0.0);
        let canonical_displacement = if reverse {
            -*displacement
        } else {
            *displacement
        };
        let mut result =
            self.minimum_image_displacement_oriented(&canonical_displacement, max_search_nodes)?;
        if reverse {
            for component in &mut result.image_offset.periods {
                *component = component.checked_neg().ok_or(
                    PeriodicLatticeError::CoordinatePrecisionLimit { axis: 0 },
                )?;
            }
            result.displacement = -result.displacement;
        }
        Ok(result)
    }

    fn minimum_image_displacement_oriented(
        &self,
        displacement: &SVector<f64, D>,
        max_search_nodes: usize,
    ) -> Result<ClosestLatticeImage<D>, PeriodicLatticeError> {
        if max_search_nodes == 0 {
            return Err(PeriodicLatticeError::InvalidSearchBudget);
        }
        if !displacement.iter().all(|value| value.is_finite()) {
            return Err(PeriodicLatticeError::NumericRange {
                field: "minimum-image displacement",
            });
        }

        let target = -(self.q.transpose() * displacement);
        if !target.iter().all(|value| value.is_finite()) {
            return Err(PeriodicLatticeError::NumericRange {
                field: "QR transformed displacement",
            });
        }

        // Babai nearest-plane initial point, back-substituted through R.
        let mut initial_offset = [0_i64; D];
        for row in (0..D).rev() {
            let mut upper_sum = 0.0;
            for column in (row + 1)..D {
                upper_sum += self.r[(row, column)] * initial_offset[column] as f64;
            }
            let center = (target[row] - upper_sum) / self.r[(row, row)];
            initial_offset[row] = nearest_i64(center, row)?;
        }

        let initial_translation = self.offset_vector(LatticeOffset::new(initial_offset))?;
        let initial_displacement = displacement + initial_translation;
        let initial_distance_squared = initial_displacement.norm_squared();
        if !initial_distance_squared.is_finite() {
            return Err(PeriodicLatticeError::NumericRange {
                field: "initial closest-image distance",
            });
        }

        let mut best = SearchBest {
            offset: initial_offset,
            displacement: initial_displacement,
            distance_squared: initial_distance_squared,
        };
        let mut current_offset = [0_i64; D];
        let mut search_nodes = 0_usize;

        sphere_decode_level(
            D as isize - 1,
            0.0,
            displacement,
            &target,
            &self.basis,
            &self.r,
            self.squared_basis_scale,
            QR_ROUNDING_PAD / self.min_relative_qr_pivot,
            max_search_nodes,
            &mut search_nodes,
            &mut current_offset,
            &mut best,
        )?;

        Ok(ClosestLatticeImage {
            image_offset: LatticeOffset::new(best.offset),
            displacement: best.displacement,
            distance_squared: best.distance_squared,
            search_nodes,
        })
    }

    /// Convert a Cartesian displacement/vector into lattice-fractional
    /// coordinates. Unlike wrap_point, this does not subtract the cell origin.
    pub fn to_fractional_coordinates(
        &self,
        cartesian_vector: &SVector<f64, D>,
    ) -> Result<SVector<f64, D>, PeriodicLatticeError> {
        if !cartesian_vector.iter().all(|value| value.is_finite()) {
            return Err(PeriodicLatticeError::NumericRange {
                field: "Cartesian vector for fractional conversion",
            });
        }
        self.solve_basis_coordinates(cartesian_vector)
    }

    fn solve_basis_coordinates(
        &self,
        cartesian: &SVector<f64, D>,
    ) -> Result<SVector<f64, D>, PeriodicLatticeError> {
        let projected = self.q.transpose() * cartesian;
        if !projected.iter().all(|value| value.is_finite()) {
            return Err(PeriodicLatticeError::NumericRange {
                field: "QR coordinate projection",
            });
        }
        let mut result = SVector::<f64, D>::zeros();
        for row in (0..D).rev() {
            let mut upper_sum = 0.0;
            for column in (row + 1)..D {
                upper_sum += self.r[(row, column)] * result[column];
            }
            result[row] = (projected[row] - upper_sum) / self.r[(row, row)];
            if !result[row].is_finite() {
                return Err(PeriodicLatticeError::NumericRange {
                    field: "fractional coordinate solve",
                });
            }
        }
        Ok(result)
    }
}

#[derive(Clone, Debug)]
struct SearchBest<const D: usize> {
    offset: [i64; D],
    displacement: SVector<f64, D>,
    distance_squared: f64,
}

fn nearest_i64(value: f64, axis: usize) -> Result<i64, PeriodicLatticeError> {
    if !value.is_finite() || value.abs() > MAX_EXACT_LATTICE_INDEX {
        return Err(PeriodicLatticeError::CoordinatePrecisionLimit { axis });
    }
    let rounded = value.round();
    if rounded < i64::MIN as f64 || rounded > i64::MAX as f64 {
        return Err(PeriodicLatticeError::CoordinatePrecisionLimit { axis });
    }
    Ok(rounded as i64)
}

#[allow(clippy::too_many_arguments)]
fn sphere_decode_level<const D: usize>(
    level: isize,
    partial_distance_squared: f64,
    original_displacement: &SVector<f64, D>,
    target: &SVector<f64, D>,
    basis: &SMatrix<f64, D, D>,
    r: &SMatrix<f64, D, D>,
    squared_basis_scale: f64,
    search_padding: f64,
    max_search_nodes: usize,
    search_nodes: &mut usize,
    offset: &mut [i64; D],
    best: &mut SearchBest<D>,
) -> Result<(), PeriodicLatticeError> {
    if level < 0 {
        let mut integer = SVector::<f64, D>::zeros();
        for axis in 0..D {
            integer[axis] = offset[axis] as f64;
        }
        let candidate_displacement = original_displacement + basis * integer;
        let candidate_distance_squared = candidate_displacement.norm_squared();
        if !candidate_distance_squared.is_finite() {
            return Err(PeriodicLatticeError::NumericRange {
                field: "sphere-decoder candidate distance",
            });
        }

        let ordering = candidate_distance_squared.total_cmp(&best.distance_squared);
        if ordering.is_lt() || (ordering.is_eq() && *offset < best.offset) {
            best.offset = *offset;
            best.displacement = candidate_displacement;
            best.distance_squared = candidate_distance_squared;
        }
        return Ok(());
    }

    let row = level as usize;
    let diagonal = r[(row, row)];
    let mut upper_sum = 0.0;
    for column in (row + 1)..D {
        upper_sum += r[(row, column)] * offset[column] as f64;
    }
    let center = (target[row] - upper_sum) / diagonal;
    let remaining = best.distance_squared - partial_distance_squared;
    let distance_pad = search_padding * best.distance_squared.max(squared_basis_scale);
    if remaining < -distance_pad {
        return Ok(());
    }
    let radius = ((remaining + distance_pad).max(0.0)).sqrt() / diagonal.abs();
    if !center.is_finite() || !radius.is_finite() {
        return Err(PeriodicLatticeError::NumericRange {
            field: "sphere-decoder interval",
        });
    }

    let integer_rounding_pad =
        search_padding * center.abs().max(radius).max(1.0);
    let lower = (center - radius - integer_rounding_pad).ceil();
    let upper = (center + radius + integer_rounding_pad).floor();
    if !lower.is_finite()
        || !upper.is_finite()
        || lower < i64::MIN as f64
        || upper > i64::MAX as f64
        || lower.abs().max(upper.abs()) > MAX_EXACT_LATTICE_INDEX
    {
        return Err(PeriodicLatticeError::CoordinatePrecisionLimit { axis: row });
    }
    if lower > upper {
        return Ok(());
    }

    let mut value = lower as i64;
    let final_value = upper as i64;
    loop {
        if *search_nodes >= max_search_nodes {
            return Err(PeriodicLatticeError::SearchBudgetExceeded {
                max_nodes: max_search_nodes,
            });
        }
        *search_nodes += 1;
        offset[row] = value;

        let row_error = diagonal * (value as f64 - center);
        let next_partial = partial_distance_squared + row_error * row_error;
        let branch_pad = search_padding * best.distance_squared.max(squared_basis_scale);
        if next_partial <= best.distance_squared + branch_pad {
            sphere_decode_level(
                level - 1,
                next_partial,
                original_displacement,
                target,
                basis,
                r,
                squared_basis_scale,
                search_padding,
                max_search_nodes,
                search_nodes,
                offset,
                best,
            )?;
        }

        if value == final_value {
            break;
        }
        value = value
            .checked_add(1)
            .ok_or(PeriodicLatticeError::CoordinatePrecisionLimit { axis: row })?;
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::{PeriodicLattice, PeriodicLatticeError};
    use crate::periodic::{LatticeOffset, PeriodicBox};
    use nalgebra::{SMatrix, SVector};

    fn lattice2(basis: SMatrix<f64, 2, 2>) -> PeriodicLattice<2> {
        PeriodicLattice::new(SVector::from([0.25, -0.5]), basis).unwrap()
    }

    fn close(a: f64, b: f64, tolerance: f64) {
        assert!(
            (a - b).abs() <= tolerance,
            "{a:.16e} != {b:.16e} within {tolerance:.3e}"
        );
    }

    fn brute_force_2d(
        displacement: &SVector<f64, 2>,
        basis: &SMatrix<f64, 2, 2>,
        radius: i64,
    ) -> (f64, [i64; 2], SVector<f64, 2>) {
        let mut best: Option<(f64, [i64; 2], SVector<f64, 2>)> = None;
        for x in -radius..=radius {
            for y in -radius..=radius {
                let offset = [x, y];
                let integer = SVector::from([x as f64, y as f64]);
                let candidate = displacement + basis * integer;
                let distance_squared = candidate.norm_squared();
                let replace = best.as_ref().is_none_or(|current| {
                    distance_squared < current.0
                        || (distance_squared == current.0 && offset < current.1)
                });
                if replace {
                    best = Some((distance_squared, offset, candidate));
                }
            }
        }
        best.unwrap()
    }

    #[test]
    fn skewed_2d_closest_image_matches_independent_integer_enumeration() {
        let basis = SMatrix::<f64, 2, 2>::from_row_slice(&[2.0, 1.4, 0.0, 1.5]);
        let lattice = lattice2(basis.clone());
        let displacement = SVector::from([1.71, 1.08]);
        let actual = lattice
            .minimum_image_displacement(&displacement, 10_000)
            .unwrap();
        let (expected_distance_squared, expected_offset, expected_displacement) =
            brute_force_2d(&displacement, &basis, 12);

        assert_eq!(actual.image_offset.periods, expected_offset);
        close(actual.distance_squared, expected_distance_squared, 1e-12);
        assert!((actual.displacement - expected_displacement).norm() < 1e-12);
    }

    #[test]
    fn triclinic_3d_closest_image_matches_independent_integer_enumeration() {
        let basis = SMatrix::<f64, 3, 3>::from_row_slice(&[
            2.0, 0.8, 0.2,
            0.0, 1.7, 0.6,
            0.0, 0.0, 1.4,
        ]);
        let lattice = PeriodicLattice::new(SVector::zeros(), basis.clone()).unwrap();
        let displacement = SVector::from([1.2, 0.95, 0.82]);
        let actual = lattice
            .minimum_image_displacement(&displacement, 100_000)
            .unwrap();

        let mut best: Option<(f64, [i64; 3], SVector<f64, 3>)> = None;
        for x in -10_i64..=10 {
            for y in -10_i64..=10 {
                for z in -10_i64..=10 {
                    let offset = [x, y, z];
                    let integer = SVector::from([x as f64, y as f64, z as f64]);
                    let candidate = displacement + basis * integer;
                    let distance_squared = candidate.norm_squared();
                    let replace = best.as_ref().is_none_or(|current| {
                        distance_squared < current.0
                            || (distance_squared == current.0 && offset < current.1)
                    });
                    if replace {
                        best = Some((distance_squared, offset, candidate));
                    }
                }
            }
        }
        let expected = best.unwrap();
        assert_eq!(actual.image_offset.periods, expected.1);
        close(actual.distance_squared, expected.0, 1e-12);
        assert!((actual.displacement - expected.2).norm() < 1e-12);
    }

    fn next_random(state: &mut u64) -> u64 {
        *state = state
            .wrapping_mul(6_364_136_223_846_793_005)
            .wrapping_add(1_442_695_040_888_963_407);
        *state
    }

    fn random_range(state: &mut u64, lower: f64, upper: f64) -> f64 {
        let bits = next_random(state) >> 11;
        lower + (upper - lower) * (bits as f64 / ((1_u64 << 53) as f64))
    }

    #[test]
    fn randomized_2d_closest_image_matches_brute_force_oracle() {
        let basis = SMatrix::<f64, 2, 2>::from_row_slice(&[2.0, 1.4, 0.0, 1.5]);
        let lattice = lattice2(basis);
        let mut seed = 0x5452_4943_4c49_4e49_u64;

        for case in 0..2_000 {
            let displacement = SVector::from([
                random_range(&mut seed, -12.0, 12.0),
                random_range(&mut seed, -12.0, 12.0),
            ]);
            let actual = lattice
                .minimum_image_displacement(&displacement, 20_000)
                .unwrap_or_else(|error| panic!("case={case} closest-image error: {error}"));
            let (distance, offset, vector) = brute_force_2d(&displacement, &basis, 12);
            assert_eq!(actual.image_offset.periods, offset, "case={case}");
            close(actual.distance_squared, distance, 2e-11);
            assert!((actual.displacement - vector).norm() < 2e-11, "case={case}");
        }
    }

    #[test]
    fn randomized_3d_closest_image_matches_brute_force_oracle() {
        let basis = SMatrix::<f64, 3, 3>::from_row_slice(&[
            2.0, 0.8, 0.2,
            0.0, 1.7, 0.6,
            0.0, 0.0, 1.4,
        ]);
        let lattice = PeriodicLattice::new(SVector::zeros(), basis).unwrap();
        let mut seed = 0x3344_5452_4943_4c49_u64;

        for case in 0..160 {
            let displacement = SVector::from([
                random_range(&mut seed, -8.0, 8.0),
                random_range(&mut seed, -8.0, 8.0),
                random_range(&mut seed, -8.0, 8.0),
            ]);
            let actual = lattice
                .minimum_image_displacement(&displacement, 50_000)
                .unwrap_or_else(|error| panic!("case={case} closest-image error: {error}"));

            let mut best: Option<(f64, [i64; 3], SVector<f64, 3>)> = None;
            for x in -8_i64..=8 {
                for y in -8_i64..=8 {
                    for z in -8_i64..=8 {
                        let offset = [x, y, z];
                        let integer = SVector::from([x as f64, y as f64, z as f64]);
                        let candidate = displacement + basis * integer;
                        let distance_squared = candidate.norm_squared();
                        let replace = best.as_ref().is_none_or(|current| {
                            distance_squared < current.0
                                || (distance_squared == current.0 && offset < current.1)
                        });
                        if replace {
                            best = Some((distance_squared, offset, candidate));
                        }
                    }
                }
            }
            let expected = best.unwrap();
            assert_eq!(actual.image_offset.periods, expected.1, "case={case}");
            close(actual.distance_squared, expected.0, 2e-11);
            assert!((actual.displacement - expected.2).norm() < 2e-11, "case={case}");
        }
    }

    #[test]
    fn exact_half_cell_tie_is_deterministic_and_reversal_odd() {
        let lattice = lattice2(SMatrix::<f64, 2, 2>::identity());
        let positive = lattice
            .minimum_image_displacement(&SVector::from([0.5, 0.0]), 100)
            .unwrap();
        let negative = lattice
            .minimum_image_displacement(&SVector::from([-0.5, 0.0]), 100)
            .unwrap();
        assert_eq!(positive.image_offset.periods, [-1, 0]);
        assert_eq!(positive.displacement, SVector::from([-0.5, 0.0]));
        assert_eq!(negative.image_offset.periods, [1, 0]);
        assert_eq!(negative.displacement, SVector::from([0.5, 0.0]));
    }

    #[test]
    fn minimum_image_reversal_is_odd_for_skew_cells() {
        let lattice = lattice2(SMatrix::<f64, 2, 2>::from_row_slice(&[
            2.0, 1.4, 0.0, 1.5,
        ]));
        let mut seed = 0x5245_5645_5253_414c_u64;
        for case in 0..2_000 {
            let displacement = SVector::from([
                random_range(&mut seed, -20.0, 20.0),
                random_range(&mut seed, -20.0, 20.0),
            ]);
            let forward = lattice
                .minimum_image_displacement(&displacement, 30_000)
                .unwrap_or_else(|error| panic!("forward case={case}: {error}"));
            let reverse = lattice
                .minimum_image_displacement(&(-displacement), 30_000)
                .unwrap_or_else(|error| panic!("reverse case={case}: {error}"));
            assert_eq!(
                reverse.image_offset.periods,
                [
                    -forward.image_offset.periods[0],
                    -forward.image_offset.periods[1],
                ],
                "image reversal mismatch at case {case}"
            );
            assert!(
                (reverse.displacement + forward.displacement).norm() < 2e-11,
                "displacement reversal mismatch at case {case}"
            );
            assert!(
                (reverse.distance_squared - forward.distance_squared).abs() < 2e-11,
                "distance mismatch at case {case}"
            );
        }
    }

    #[test]
    fn lattice_translation_does_not_change_minimum_image_displacement() {
        let basis = SMatrix::<f64, 2, 2>::from_row_slice(&[2.0, 1.4, 0.0, 1.5]);
        let lattice = lattice2(basis);
        let displacement = SVector::from([0.93, -0.77]);
        let original = lattice
            .minimum_image_displacement(&displacement, 10_000)
            .unwrap();
        let shift = LatticeOffset::new([3, -2]);
        let translated_displacement = displacement + lattice.offset_vector(shift).unwrap();
        let translated = lattice
            .minimum_image_displacement(&translated_displacement, 10_000)
            .unwrap();

        assert!((translated.displacement - original.displacement).norm() < 1e-11);
        assert_eq!(
            translated.image_offset.periods,
            [
                original.image_offset.periods[0] - shift.periods[0],
                original.image_offset.periods[1] - shift.periods[1]
            ]
        );
    }

    #[test]
    fn unimodular_basis_change_preserves_physical_nearest_image() {
        let basis = SMatrix::<f64, 2, 2>::from_row_slice(&[2.0, 1.4, 0.0, 1.5]);
        let shear = SMatrix::<f64, 2, 2>::from_row_slice(&[1.0, 1.0, 0.0, 1.0]);
        let changed_basis = basis * shear;
        let original_lattice = lattice2(basis);
        let changed_lattice = lattice2(changed_basis);
        let displacement = SVector::from([1.31, 0.66]);

        let original = original_lattice
            .minimum_image_displacement(&displacement, 10_000)
            .unwrap();
        let changed = changed_lattice
            .minimum_image_displacement(&displacement, 10_000)
            .unwrap();

        assert!((changed.displacement - original.displacement).norm() < 1e-11);
        close(changed.distance_squared, original.distance_squared, 1e-11);
        let transformed_offset = [
            changed.image_offset.periods[0] + changed.image_offset.periods[1],
            changed.image_offset.periods[1],
        ];
        assert_eq!(transformed_offset, original.image_offset.periods);
    }

    #[test]
    fn randomized_unimodular_shear_preserves_closest_cartesian_image() {
        let basis = SMatrix::<f64, 2, 2>::from_row_slice(&[2.0, 1.4, 0.0, 1.5]);
        let original_lattice = lattice2(basis.clone());
        let mut seed = 0x554e_494d_4f44_554c_u64;

        for case in 0..256 {
            let shear = (next_random(&mut seed) % 9) as i32 - 4;
            let transform = SMatrix::<f64, 2, 2>::from_row_slice(&[
                1.0,
                shear as f64,
                0.0,
                1.0,
            ]);
            let changed_lattice = lattice2(basis.clone() * transform);
            let displacement = SVector::from([
                random_range(&mut seed, -7.0, 7.0),
                random_range(&mut seed, -7.0, 7.0),
            ]);

            let original = original_lattice
                .minimum_image_displacement(&displacement, 30_000)
                .unwrap_or_else(|error| panic!("original case={case}: {error}"));
            let changed = changed_lattice
                .minimum_image_displacement(&displacement, 30_000)
                .unwrap_or_else(|error| panic!("changed case={case}, shear={shear}: {error}"));

            assert!((changed.displacement - original.displacement).norm() < 2e-10);
            close(changed.distance_squared, original.distance_squared, 2e-10);
            let transformed_offset = [
                changed.image_offset.periods[0] + shear as i64 * changed.image_offset.periods[1],
                changed.image_offset.periods[1],
            ];
            assert_eq!(
                transformed_offset,
                original.image_offset.periods,
                "case={case}, shear={shear}"
            );
        }
    }

    #[test]
    fn wrapping_reconstructs_cartesian_input_through_integer_lattice_offset() {
        let basis = SMatrix::<f64, 2, 2>::from_row_slice(&[2.0, 1.4, 0.0, 1.5]);
        let lattice = lattice2(basis);
        let point = SVector::from([13.4, -8.1]);
        let wrapped = lattice.wrap_point(&point).unwrap();

        let fractional = lattice
            .solve_basis_coordinates(&(wrapped.position - lattice.origin()))
            .unwrap();
        assert!(fractional.iter().all(|value| (0.0..1.0).contains(value)));
        let restored = lattice
            .apply_offset(&wrapped.position, wrapped.image_offset)
            .unwrap();
        assert!((restored - point).norm() < 1e-11);
    }

    #[test]
    fn rotated_lattice_and_displacement_rotate_the_answer() {
        let basis = SMatrix::<f64, 2, 2>::from_row_slice(&[2.0, 1.4, 0.0, 1.5]);
        let rotation = SMatrix::<f64, 2, 2>::new(0.0, -1.0, 1.0, 0.0);
        let lattice = lattice2(basis.clone());
        let rotated_lattice = lattice2(rotation * basis);
        let displacement = SVector::from([1.31, 0.66]);
        let original = lattice
            .minimum_image_displacement(&displacement, 10_000)
            .unwrap();
        let rotated = rotated_lattice
            .minimum_image_displacement(&(rotation * displacement), 10_000)
            .unwrap();

        assert!((rotated.displacement - rotation * original.displacement).norm() < 1e-11);
        close(rotated.distance_squared, original.distance_squared, 1e-11);
        assert_eq!(rotated.image_offset, original.image_offset);
    }

    #[test]
    fn search_budget_exhaustion_is_not_silently_returned_as_minimum() {
        let lattice = lattice2(SMatrix::<f64, 2, 2>::identity());
        assert_eq!(
            lattice.minimum_image_displacement(&SVector::from([0.5, 0.0]), 1),
            Err(PeriodicLatticeError::SearchBudgetExceeded { max_nodes: 1 })
        );
    }

    #[test]
    fn strong_but_accepted_skew_matches_brute_force_oracle() {
        let basis = SMatrix::<f64, 2, 2>::from_row_slice(&[1.0, 0.9999, 0.0, 0.002]);
        let lattice = lattice2(basis.clone());
        assert!(lattice.min_relative_qr_pivot() >= 1.0e-8);

        for displacement in [
            SVector::from([0.2, 0.001]),
            SVector::from([-0.8, 0.0015]),
            SVector::from([2.4, -0.003]),
        ] {
            let actual = lattice
                .minimum_image_displacement(&displacement, 100_000)
                .unwrap();
            let (distance, offset, vector) = brute_force_2d(&displacement, &basis, 64);
            assert_eq!(actual.image_offset.periods, offset);
            close(actual.distance_squared, distance, 1e-9);
            assert!((actual.displacement - vector).norm() < 1e-9);
        }
    }

    #[test]
    fn near_singular_basis_is_rejected() {
        let basis = SMatrix::<f64, 2, 2>::from_row_slice(&[1.0, 1.0, 0.0, 1.0e-14]);
        assert_eq!(
            PeriodicLattice::new(SVector::zeros(), basis).unwrap_err(),
            PeriodicLatticeError::DegenerateBasis { column: 1 }
        );
    }

    #[test]
    fn closest_image_is_invariant_under_uniform_unit_scaling() {
        let basis = SMatrix::<f64, 2, 2>::from_row_slice(&[2.0, 1.4, 0.0, 1.5]);
        let displacement = SVector::from([1.31, 0.66]);
        let reference = lattice2(basis.clone())
            .minimum_image_displacement(&displacement, 10_000)
            .unwrap();

        for scale in [1.0e-6_f64, 1.0e6] {
            let scaled_basis = basis * scale;
            let scaled_displacement = displacement * scale;
            let scaled = lattice2(scaled_basis)
                .minimum_image_displacement(&scaled_displacement, 10_000)
                .unwrap();

            assert_eq!(scaled.image_offset, reference.image_offset);
            assert!((scaled.displacement / scale - reference.displacement).norm() < 1e-9);
            close(
                scaled.distance_squared / (scale * scale),
                reference.distance_squared,
                1e-9,
            );
        }
    }

    #[test]
    fn orthogonal_lattice_matches_orthogonal_periodic_box_minimum_image() {
        let basis = SMatrix::<f64, 2, 2>::from_diagonal(&SVector::from([10.0, 7.0]));
        let lattice = PeriodicLattice::new(SVector::zeros(), basis).unwrap();
        let box_domain = PeriodicBox::new(
            SVector::zeros(),
            SVector::from([10.0, 7.0]),
            [true, true],
        )
        .unwrap();

        for displacement in [
            SVector::from([4.9, -3.4]),
            SVector::from([9.2, -6.8]),
            SVector::from([-14.7, 19.1]),
        ] {
            let a = lattice
                .minimum_image_displacement(&displacement, 10_000)
                .unwrap();
            let b = box_domain.minimum_image_displacement(&displacement).unwrap();
            assert!((a.displacement - b).norm() < 1e-11);
        }
    }

    #[test]
    fn rejects_non_finite_inputs_and_zero_search_budget() {
        let lattice = lattice2(SMatrix::<f64, 2, 2>::identity());
        assert_eq!(
            lattice.minimum_image_displacement(&SVector::zeros(), 0),
            Err(PeriodicLatticeError::InvalidSearchBudget)
        );
        assert!(matches!(
            lattice.minimum_image_displacement(&SVector::from([f64::NAN, 0.0]), 100),
            Err(PeriodicLatticeError::NumericRange { .. })
        ));
    }
}
